WITH remaining_keys AS (SELECT carrier, id FROM shipments INTERSECT ALL SELECT carrier, id FROM shipments WHERE status = 'DELIVERED'), kept_rows AS (SELECT s.* FROM shipments s JOIN remaining_keys k ON s.carrier = k.carrier AND s.id = k.id) SELECT id, carrier, shipped_date, delivered_date, cost, status, CASE WHEN carrier RLIKE '^(FedEx|Kerry)$' THEN 'GROUP_B' WHEN carrier RLIKE '^(DHL|Flash)$' THEN 'GROUP_A' ELSE 'CORE' END AS carrier_zone FROM kept_rows;
